import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

lines=open('opt_gfn2.xyz').read().splitlines()
n=int(lines[0]); syms=[]; X=[]
for l in lines[2:2+n]:
    p=l.split(); syms.append(p[0]); X.append([float(v) for v in p[1:4]])
X=np.array(X)
rcov={"H":0.31,"C":0.76,"N":0.71,"Au":1.36}
col={"H":"#dddddd","C":"#555555","N":"#3050f8","Au":"#ffd123"}
rad={"H":0.25,"C":0.5,"N":0.5,"Au":0.9}
# bonds incl Au-C up to 2.6
bonds=[]
for i in range(n):
    for j in range(i+1,n):
        dd=np.linalg.norm(X[i]-X[j])
        lim = rcov[syms[i]]+rcov[syms[j]]+0.45
        if "Au" in (syms[i],syms[j]): lim=2.65
        if dd<lim: bonds.append((i,j))

fig=plt.figure(figsize=(18,8))
for k,(el,az) in enumerate([(20,-60),(90,-90)]):
    ax=fig.add_subplot(1,2,k+1,projection='3d')
    for (i,j) in bonds:
        ax.plot([X[i,0],X[j,0]],[X[i,1],X[j,1]],[X[i,2],X[j,2]],color='#888888',lw=1.5,zorder=1)
    for i in range(n):
        ax.scatter(X[i,0],X[i,1],X[i,2],s=rad[syms[i]]*380,c=col[syms[i]],edgecolors='k',linewidths=0.3,zorder=2)
    ax.view_init(elev=el,azim=az)
    ax.set_box_aspect((1,1,0.8)); ax.set_axis_off()
plt.tight_layout(); plt.savefig("render.png",dpi=110)
print("saved render.png, bonds:",len(bonds))
